package com.smartdoc.ai.provider; import com.fasterxml.jackson.annotation.JsonInclude; import java.time.LocalDateTime;
@JsonInclude(JsonInclude.Include.NON_NULL) public class ProviderView { public Long id;public String displayName,presetCode,protocol,baseUrl,model,maskedKey;public boolean supportsText,supportsVision,enabled,keyConfigured,persistenceAvailable;public LocalDateTime createdAt,updatedAt; public static ProviderView of(AiProviderConfig p,boolean configured,boolean persistent){ProviderView v=new ProviderView();v.id=p.getId();v.displayName=p.getDisplayName();v.presetCode=p.getPresetCode();v.protocol=p.getProtocol();v.baseUrl=p.getBaseUrl();v.model=p.getModel();v.supportsText=Boolean.TRUE.equals(p.getSupportsText());v.supportsVision=Boolean.TRUE.equals(p.getSupportsVision());v.enabled=Boolean.TRUE.equals(p.getEnabled());v.keyConfigured=configured;v.maskedKey=configured?"********":null;v.persistenceAvailable=persistent;v.createdAt=p.getCreatedAt();v.updatedAt=p.getUpdatedAt();return v;} }
